create function public.vet_execute(p_operation text,p_payload jsonb default '{}',p_key uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
begin return private.execute_before_request_names(p_operation,private.request_names(coalesce(p_payload,'{}')),p_key);end;$$;
revoke all on function public.vet_execute(text,jsonb,uuid) from public;grant execute on function public.vet_execute(text,jsonb,uuid) to authenticated;

create unique index active_appointment_sale on public.vetsalebuyowner("appointmentId") where not deleted and "appointmentId" is not null;
alter function private.commercial_operation(text,jsonb) rename to commercial_before_appointment_collection;
create function private.commercial_operation(action text,payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare appointment public.vetappoointments;definition public.vetappointmenttypes;vaccine public.vetvaccine;result jsonb;lines jsonb;price numeric;configured numeric;custom boolean:=coalesce((payload->>'enterAmount')::boolean,false);
begin
 if action<>'createcollection' then return private.commercial_before_appointment_collection(action,payload);end if;
 if nullif(payload->>'collectionId','') is null then raise exception 'Tahsilat için randevu seçin';end if;
 select * into appointment from public.vetappoointments where id=(payload->>'collectionId')::uuid and not deleted for update;
 if not found then raise exception 'Randevu bulunamadı';end if;
 perform private.require_access('finance',true,appointment.branch_id);
 if not appointment."isCompleted" or appointment."isPaymentReceived" or exists(select 1 from public.vetsalebuyowner where "appointmentId"=appointment.id and not deleted) then raise exception 'Randevu tamamlanmamış veya zaten ücretlendirilmiş';end if;
 if (payload->>'customerId')::uuid is distinct from appointment."customerId" then raise exception 'Müşteri ve randevu eşleşmiyor';end if;
 select * into definition from public.vetappointmenttypes where type=appointment."appointmentType" and branch_id=appointment.branch_id and not deleted order by "recId" limit 1;
 if appointment."vaccineId" is not null then
  select * into vaccine from public.vetvaccine where id=appointment."vaccineId" and branch_id=appointment.branch_id and not deleted;
  if not found then raise exception 'Aşı tanımı bulunamadı';end if;
  select sum(m.quantity*p."sellingPrice") into configured from public.vetvaccinemedicine m join public.vetproducts p on p.id=m."productId" and p.branch_id=m.branch_id and not p.deleted where m."vaccineId"=vaccine.id and not m.deleted;
  if coalesce(configured,0)<=0 then raise exception 'Aşı ürünlerini ve fiyatlarını tanımlayın';end if;
  price:=case when custom then (payload->>'amount')::numeric else configured end;
  if price is null or price<=0 or price::text in ('NaN','Infinity','-Infinity') then raise exception 'Geçerli tutar girin';end if;
  select jsonb_agg(jsonb_build_object('product',p.id,'quantity',m.quantity,'unitPrice',p."sellingPrice"*price/configured,'vat',case when custom then nullif(payload->>'taxisId','') else null end)) into lines from public.vetvaccinemedicine m join public.vetproducts p on p.id=m."productId" and p.branch_id=m.branch_id and not p.deleted where m."vaccineId"=vaccine.id and not m.deleted;
  result:=private.create_sale(jsonb_build_object('customerId',appointment."customerId",'branch_id',appointment.branch_id,'paymentType',payload->'paymentType','type',1,'trans',lines));
 else
  price:=case when custom or not coalesce(definition."isDefaultPrice",false) then (payload->>'amount')::numeric else definition.price end;
  if price is null or price<=0 or price::text in ('NaN','Infinity','-Infinity') then raise exception 'Geçerli tutar girin';end if;
  result:=private.create_sale(jsonb_build_object('customerId',appointment."customerId",'branch_id',appointment.branch_id,'paymentType',payload->'paymentType','type',1,'price',price,'serviceTaxId',case when custom then nullif(payload->>'taxisId','')::uuid else definition."taxisId" end));
 end if;
 update public.vetsalebuyowner set "appointmentId"=appointment.id,"isAppointment"=true where id=(result->>'id')::uuid;
 perform private.collect_sale(jsonb_build_object('saleBuyId',result->>'id','amount',result->'amount','paymentId',payload->'paymentType'));
 update public.vetpaymentcollection set "collectionId"=appointment.id where "saleBuyId"=(result->>'id')::uuid and not deleted;
 update public.vetappoointments set "isPaymentReceived"=true,"updateDate"=now() where id=appointment.id;
 return to_jsonb(result->>'id');
end;$$;
revoke all on function private.commercial_operation(text,jsonb) from public,authenticated;

alter function private.read_operation(text,text,jsonb) rename to read_operation_before_appointment_collection;
create function private.read_operation(action text,entity text,payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if action='getpaymenttransactionlist' then
  perform private.require_access('finance',false,private.branch());
  return (select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'appointmentType',a."appointmentType",'vaccineid',a."vaccineId",'textValue',concat_ws(' / ',t.remark,v."vaccineName"),'isDefaultPrice',coalesce(t."isDefaultPrice",false),'price',t.price,'sellingPrice',coalesce(v."totalSaleAmount",t.price,0),'taxisId',t."taxisId") order by a."beginDate"),'[]') from public.vetappoointments a left join public.vetappointmenttypes t on t.type=a."appointmentType" and t.branch_id=a.branch_id and not t.deleted left join public.vetvaccine v on v.id=a."vaccineId" and v.branch_id=a.branch_id and not v.deleted where not a.deleted and a."isCompleted" and not a."isPaymentReceived" and a."customerId"=(payload->>'customerId')::uuid and private.allowed('finance',false,a.branch_id) and not exists(select 1 from public.vetsalebuyowner where "appointmentId"=a.id and not deleted));
 end if;
 return private.read_operation_before_appointment_collection(action,entity,payload);
end;$$;
revoke all on function private.read_operation(text,text,jsonb) from public,authenticated;

create or replace function private.create_sale_before_relations(payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare branch uuid:=coalesce(nullif(payload->>'branch_id','')::uuid,private.branch());
 header public.vetsalebuyowner; product public.vetproducts; item jsonb; lines jsonb; count numeric; unit_price numeric; rate numeric; vat numeric; net numeric; discount numeric; included boolean; tax_id uuid; kind integer:=coalesce((payload->>'type')::int,1);
begin
 perform private.require_access('finance',true,branch);
 if kind not in (1,2) then raise exception 'Geçersiz işlem türü';end if;
 if nullif(payload->>'customerId','') is not null and payload->>'customerId'<>'00000000-0000-0000-0000-000000000000' and not exists(select 1 from public.vetcustomers where id=(payload->>'customerId')::uuid and branch_id=branch and not deleted) then raise exception 'Müşteri bulunamadı';end if;
 lines:=payload->'trans';
 if lines is null and payload ? 'productId' then lines:=jsonb_build_array(jsonb_build_object('product',payload->>'productId','quantity',payload->'amount'));end if;
 if coalesce(jsonb_array_length(lines),0)=0 and coalesce((payload->>'price')::numeric,0)<=0 then raise exception 'Satış kalemi zorunlu';end if;
 insert into public.vetsalebuyowner(branch_id,type,"customerId","supplierId",date,remark,"examinationsId","isExaminations","accomodationId","isAccomodation")
 values(branch,kind,nullif(nullif(payload->>'customerId',''),'00000000-0000-0000-0000-000000000000')::uuid,nullif(nullif(payload->>'supplierId',''),'00000000-0000-0000-0000-000000000000')::uuid,coalesce((payload->>'date')::timestamptz,now()),coalesce(payload->>'remark',''),nullif(nullif(payload->>'examinationId',''),'00000000-0000-0000-0000-000000000000')::uuid,coalesce((payload->>'isExaminations')::boolean,false),nullif(payload->>'accomodationId','')::uuid,coalesce((payload->>'isAccomodation')::boolean,false)) returning * into header;
 -- Lock products in stable order before applying any quantities.
 perform p.id from public.vetproducts p where p.id in (select coalesce(x->>'product',x->>'productId')::uuid from jsonb_array_elements(coalesce(lines,'[]')) x) order by p.id for update;
 for item in select value from jsonb_array_elements(coalesce(lines,'[]')) loop
  select * into product from public.vetproducts where id=coalesce(item->>'product',item->>'productId')::uuid and not deleted and branch_id=branch;
  if not found then raise exception 'Ürün bulunamadı';end if;
  count:=(item->>'quantity')::numeric;discount:=coalesce((item->>'discount')::numeric,0);
  if count is null or count<=0 or discount<0 or count::text in ('NaN','Infinity','-Infinity') or discount::text in ('NaN','Infinity','-Infinity') then raise exception 'Miktar pozitif, indirim sıfır veya pozitif olmalı';end if;
  unit_price:=coalesce((item->>'unitPrice')::numeric,case when kind=1 then product."sellingPrice" else product."buyingPrice" end);
  if unit_price is null or unit_price<0 or unit_price::text in ('NaN','Infinity','-Infinity') then raise exception 'Geçersiz birim fiyat';end if;
  included:=case when kind=1 then product."sellingIncludeKDV" else product."buyingIncludeKDV" end;
  tax_id:=coalesce(nullif(item->>'vat','')::uuid,product."taxisId");
  select "taxRatio" into rate from public.vettaxis where id=tax_id and not deleted and branch_id=branch;
  if tax_id is not null and not found then raise exception 'Vergi ve şube eşleşmiyor';end if;
  if rate<0 or rate>100 or rate::text in ('NaN','Infinity','-Infinity') then raise exception 'Geçersiz vergi oranı';end if;
  rate:=coalesce(rate,0);
  vat:=case when coalesce(included,false) then trunc(unit_price*count-unit_price*count/(1+rate/100),2) else unit_price*count*rate/100 end;
  net:=private.round_even(unit_price*count)-case when coalesce(included,false) then vat else 0 end;
  if unit_price<0 or net+vat<discount then raise exception 'Geçersiz fiyat veya indirim';end if;
  insert into public.vetsalebuytrans(branch_id,"ownerId","productId",quantity,amount,price,discount,"netPrice","vatAmount","vatIncluded","taxisId") values(branch,header.id,product.id,count,count,unit_price,discount,net,vat,included,tax_id);
  if product."productTypeId"<>3 then perform private.stock_change(product.id,branch,case when kind=1 then -count else count end,'invoice',header.id);end if;
 end loop;
 if coalesce((payload->>'price')::numeric,0)>0 then
  unit_price:=(payload->>'price')::numeric;
  if unit_price::text in ('NaN','Infinity','-Infinity') then raise exception 'Geçersiz hizmet tutarı';end if;
  tax_id:=nullif(payload->>'serviceTaxId','')::uuid;
  select "taxRatio" into rate from public.vettaxis where id=tax_id and not deleted and branch_id=branch;
  if tax_id is not null and not found then raise exception 'Vergi ve şube eşleşmiyor';end if;
  if rate<0 or rate>100 or rate::text in ('NaN','Infinity','-Infinity') then raise exception 'Geçersiz vergi oranı';end if;
  vat:=private.round_even(unit_price*coalesce(rate,0)/100);
  insert into public.vetsalebuytrans(branch_id,"ownerId",quantity,amount,price,"netPrice",discount,"vatAmount","taxisId") values(branch,header.id,1,1,unit_price,private.round_even(unit_price),0,vat,tax_id);
 end if;
 update public.vetsalebuyowner h set "invoiceNo"='#'||h."recId", "netPrice"=t.net, "kDV"=t.vat,discount=t.discount,total=t.net+t.vat-t.discount from
 (select private.round_even(sum(l."netPrice")) net,private.round_even(sum(l."vatAmount")) vat,private.round_even(sum(l.discount)) discount from public.vetsalebuytrans l where l."ownerId"=header.id) t where h.id=header.id returning h.* into header;
 return jsonb_build_object('id',header.id,'amount',header.total);
end;$$;


revoke all on function private.create_sale_before_relations(jsonb) from public,authenticated;

create function private.appointment_paid(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.vetsalebuyowner s where s."appointmentId"=p_id and not s.deleted and (select coalesce(sum(c.total),0) from public.vetpaymentcollection c where c."saleBuyId"=s.id and not c.deleted)>=s.total);
$$;
create function private.sync_appointment_payment() returns trigger language plpgsql security definer set search_path='' as $$
declare before_data jsonb:=to_jsonb(old);after_data jsonb:=to_jsonb(new);target uuid;
begin
 if tg_table_name='vetsalebuyowner' then
  for target in select distinct v::uuid from unnest(array[before_data->>'appointmentId',after_data->>'appointmentId']) v where v is not null loop
   update public.vetappoointments set "isPaymentReceived"=private.appointment_paid(target),"updateDate"=now() where id=target;
  end loop;
 else
  for target in select distinct "appointmentId" from public.vetsalebuyowner where id in ((before_data->>'saleBuyId')::uuid,(after_data->>'saleBuyId')::uuid) and "appointmentId" is not null loop
   update public.vetappoointments set "isPaymentReceived"=private.appointment_paid(target),"updateDate"=now() where id=target;
  end loop;
 end if;
 return coalesce(new,old);
end;$$;
create trigger appointment_sale_payment after insert or update or delete on public.vetsalebuyowner for each row execute function private.sync_appointment_payment();
create trigger appointment_collection_payment after insert or update or delete on public.vetpaymentcollection for each row execute function private.sync_appointment_payment();
revoke all on function private.appointment_paid(uuid),private.sync_appointment_payment() from public,authenticated;

alter function private.appointment_operation(text,jsonb) rename to appointment_operation_before_payment_state;
create function private.appointment_operation(action text,payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare b uuid;paid boolean;
begin
 if action='updatepaymentreceivedappointment' then
  select branch_id into b from public.vetappoointments where id=(payload->>'id')::uuid and not deleted;
  if not found then raise exception 'Randevu bulunamadı';end if;
  perform private.require_access('finance',true,b);
  paid:=private.appointment_paid((payload->>'id')::uuid);
  if coalesce((payload->>'isPaymentReceived')::boolean,true)<>paid then raise exception 'Ödeme durumu tahsilat kayıtlarından hesaplanır';end if;
 end if;
 return private.appointment_operation_before_payment_state(action,payload);
end;$$;
revoke all on function private.appointment_operation(text,jsonb) from public,authenticated;

create or replace function private.execute_before_request_names(p_operation text,p_payload jsonb default '{}',p_key uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare op private.operation_registry; action text; result jsonb; saved private.operation_receipts; record jsonb; child jsonb; writing boolean; sc text;
begin
 if auth.uid() is null then raise exception 'Oturum açın' using errcode='42501';end if;
 p_operation:=lower(p_operation);p_payload:=coalesce(p_payload,'{}');
 select * into op from private.operation_registry where path=p_operation;
 if not found then raise exception 'Tanımsız işlem: %',p_operation using errcode='0A000';end if;
 action:=split_part(p_operation,'/',3);
 writing:=op.mode<>'read' and action !~ '^(get|is|all)';
 if writing then
  if p_key is null then raise exception 'İşlem anahtarı zorunlu';end if;
  perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||p_operation||p_key::text,0));
  select * into saved from private.operation_receipts where actor=auth.uid() and operation=p_operation and key=p_key;
  if found then
   if saved.member_role is distinct from (select role from public.profiles where id=auth.uid()) or saved.member_branch is distinct from private.branch() then raise exception 'İşlemden sonra üyelik veya şube değişmiş' using errcode='42501';end if;
   if saved.request<>p_payload then raise exception 'İşlem anahtarı farklı bir istek için kullanılmış';end if;
   -- A replay must not bypass a disabled membership or expired subscription.
   if not private.entitled() or not exists(select 1 from public.profiles where id=auth.uid() and active) then raise exception 'Aktif üyelik gerekiyor' using errcode='42501';end if;
   if op.entity is not null then select scope into sc from private.entity_registry where name=op.entity;perform private.require_access(sc,true,private.branch());end if;
   return saved.result;
  end if;
 end if;
 if op.mode='read' then result:=private.read_operation(action,op.entity,p_payload);
 elsif op.mode='crud' then result:=private.save_entity(op.entity,p_payload,op.verb);
 elsif action in ('createvaccine','updatevaccine','detelevaccine','createvaccineexamination','updatevaccineexamination','detelevaccineappointment') then result:=private.vaccine_operation(action,p_payload);
 elsif action in ('createsale','createsalebuy') then result:=private.create_sale(p_payload);
 elsif action='createsalecollection' then result:=private.collect_sale(p_payload);
 elsif action='deletesalebuy' then result:=private.cancel_sale(p_payload);
 elsif action in ('deletecollection','deletepaychart','updatesale','updatesalebuy','updatesalecollection','createbalancesalecollection','createcollection') then result:=private.commercial_operation(action,p_payload);
 elsif action in ('createcustomer','deletecustomer','createexamination','updateexamination','deleteexamination','createpatient','updatepatient','updatecustomerbyid','updatepatientsweight','createaccomodation','updateaccomodation','deleteaccomodation','updatecheckout') then result:=private.clinical_operation(action,p_payload);
 elsif action in ('createappointment','updateappointment','deleteappointment','updateappointmentstatus','updatecompletedappointment','updatepaymentreceivedappointment') then result:=private.appointment_operation(action,p_payload);
 elsif action in ('createpatient','updatepatient','deletepatient','updatecustomerbyid','updatecustomerarchive','updatepatientsweight','createappointment','updateappointment','deleteappointment','updateappointmentstatus','updatecompletedappointment','updatepaymentreceivedappointment','updateexaminationstatus','createroom','updateroom','deleteroom','createshortcuts','updateshortcuts','deleteshortcuts') then
  result:=private.save_entity(op.entity,p_payload,op.verb);
 elsif action in ('createstocktracking','updatestocktracking','deletestocktracking') then result:=private.stock_operation(action,p_payload);
 elsif action in ('getuserslist','getvetuserslist','getactiveuser','getallusers') then
  perform private.require_access('appointments',false,private.branch());
  if action='getactiveuser' then select jsonb_build_object('id',id,'firstName',name,'lastName','','name',name,'email',email,'role',role) into result from public.profiles where id=auth.uid() and active;else select coalesce(jsonb_agg(jsonb_build_object('id',id,'firstName',name,'lastName','','name',name,'email',email,'role',role)),'[]') into result from public.profiles where active and (private.is_owner() or branch_id=private.branch());end if;
 elsif action in ('getcompany','updatecompany','gettitledefination','createtitledefination','updatetitledefination','deletetiledefination') then result:=private.settings_operation(action,p_payload);
 elsif action='getbranchlist' then
  select coalesce(jsonb_agg(to_jsonb(b)),'[]') into result from public.branches b where private.allowed('definitions',false,b.id);
 elsif action in ('createbranch','updatebranch','deletebranch','updatecompany') then
  if not private.is_owner() or not private.entitled() then raise exception 'Yönetici yetkisi gerekiyor' using errcode='42501';end if;
  if action in ('createbranch','updatebranch') and length(btrim(coalesce(p_payload->>'name',''))) not between 1 and 120 then raise exception 'Şube adı zorunlu';end if;
  if action='createbranch' then insert into public.branches(name,district,address,phone) values(p_payload->>'name',coalesce(p_payload->>'district',''),coalesce(p_payload->>'address',''),coalesce(p_payload->>'phone','')) returning to_jsonb(branches.*) into result;
  elsif action='updatebranch' then update public.branches set name=p_payload->>'name',district=coalesce(p_payload->>'district',district),address=coalesce(p_payload->>'address',address),phone=coalesce(p_payload->>'phone',phone) where id=(p_payload->>'id')::uuid returning to_jsonb(branches.*) into result;
  elsif action='deletebranch' then
   if exists(select 1 from public.profiles where branch_id=(p_payload->>'id')::uuid and active) then raise exception 'Önce şubenin aktif kullanıcılarını başka şubeye taşıyın';end if;
   update public.branches set active=false where id=(p_payload->>'id')::uuid returning to_jsonb(branches.*) into result;
  else update public.clinic_settings set name=coalesce(p_payload->>'name',name) returning to_jsonb(clinic_settings.*) into result;end if;
 elsif action='getdashboard' then result:=private.dashboard();
 elsif action in ('sendmessage','multiautosendmessage') then result:=private.customer_message(action,p_payload);
 elsif action='getsmsparameterslist' then record:=public.provider_status();result:=case when record->>'mode'='test' or (record->>'smsConfigured')::boolean then '[{"active":true,"smsIntegrationType":1}]'::jsonb else '[]'::jsonb end;
 elsif action in ('getgraphiclist','weekvisitlist','bagelslicegraphlist','getclinicalstatisticslist') then result:=private.statistics(action,p_payload);
 elsif action='getuserrolesettinglist' then result:='[]';
 else result:=private.support_operation(action,op.entity,op.verb,p_payload);
 end if;
 result:=jsonb_build_object('data',result,'isSuccessful',true,'errors','[]'::jsonb,'statusCode',200);
 if writing then insert into private.operation_receipts(actor,operation,key,request,result) values(auth.uid(),p_operation,p_key,p_payload,result);end if;
 return result;
end;$$;
revoke all on function private.execute_before_request_names(text,jsonb,uuid) from public;
revoke all on function private.execute_before_request_names(text,jsonb,uuid) from public,authenticated;

