import {createClient} from 'npm:@supabase/supabase-js@2.116.0';
const headers={'Access-Control-Allow-Origin':Deno.env.get('APP_ORIGIN')||'http://localhost:4200','Access-Control-Allow-Headers':'authorization,apikey,content-type,x-client-info','Access-Control-Allow-Methods':'POST,OPTIONS'};
Deno.serve(async req=>{
 if(req.method==='OPTIONS')return new Response(null,{headers});
 if(req.method!=='POST')return new Response('Method not allowed',{status:405,headers});
 try{
  const url=Deno.env.get('SUPABASE_URL')!;const admin=createClient(url,Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false}});
  const jwt=req.headers.get('authorization')?.replace(/^Bearer /,'');if(!jwt)return new Response('Unauthorized',{status:401,headers});
  const user=await admin.auth.getUser(jwt);if(user.error||!user.data.user)return new Response('Unauthorized',{status:401,headers});
  const profile=await admin.from('profiles').select('role,active').eq('id',user.data.user.id).single();
  const settings=await admin.from('clinic_settings').select('status,trial_ends_at').single();
  if(profile.data?.role!=='owner'||!profile.data.active||!(settings.data?.status==='paid'||settings.data?.status==='trial'&&Date.parse(settings.data.trial_ends_at)>Date.now()))return new Response('Forbidden',{status:403,headers});
  const body=await req.json();if(typeof body.email!=='string'||typeof body.name!=='string'||body.name.length>120||!['vet','reception','accountant','reader'].includes(body.role))throw new Error('Invalid member');
  const branch=await admin.from('branches').select('id').eq('id',body.branch_id).eq('active',true).single();if(branch.error)throw branch.error;
  const existing=await admin.rpc('lookup_invited_user',{p_email:body.email});if(existing.error)throw existing.error;
  let memberId=existing.data;
  if(!memberId){
   const invite=await admin.auth.admin.inviteUserByEmail(body.email,{redirectTo:Deno.env.get('APP_ORIGIN')+'/auth/callback?clinic='+encodeURIComponent(Deno.env.get('CLINIC_CODE')!),data:{name:body.name}});
   if(invite.error)throw invite.error;memberId=invite.data.user.id;
  }
  const add=await admin.rpc('add_invited_member',{p_actor:user.data.user.id,p_id:memberId,p_name:body.name,p_role:body.role,p_branch:body.branch_id});if(add.error)throw add.error;
  return Response.json({id:memberId},{headers});
 }catch{return Response.json({error:'Üye daveti tamamlanamadı. Tekrar denemeden önce üye listesini kontrol edin.'},{status:400,headers});}
});

import {createClient} from 'npm:@supabase/supabase-js@2.116.0';
import {deliver,receipt} from './providers.mjs';
Deno.serve(async req=>{
 const token=Deno.env.get('WORKER_TOKEN');if(!token||req.method!=='POST'||req.headers.get('authorization')!=='Bearer '+token)return new Response('Unauthorized',{status:401});
 const db=createClient(Deno.env.get('SUPABASE_URL')!,Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false}});
 const stored=await db.rpc('get_provider_configuration');if(stored.error)return Response.json({error:'Provider configuration unavailable'},{status:503});
 const config=stored.data;
 if(!['test','live'].includes(config.mode||''))return Response.json({error:'Provider mode must be configured'},{status:503});
 let job:any;
 try{
  const claim=await db.rpc('claim_message_job');if(claim.error)throw claim.error;job=claim.data;
  if(job){
   let result;try{result=await deliver(job,config);}catch{result={state:'unknown',safe_error:'Sağlayıcı gönderim sonucu doğrulanamadı. Tekrar göndermeden önce sağlayıcı panelini kontrol edin.'};}
   const update=await db.from('message_outbox').update({...result,updated_at:new Date().toISOString(),receipt_after:new Date(Date.now()+60000).toISOString()}).eq('id',job.id).eq('state','sending');if(update.error)throw update.error;
   return Response.json({id:job.id,state:result.state});
  }
  const pending=await db.rpc('claim_receipt_job');if(pending.error)throw pending.error;job=pending.data;
  if(job){const result=await receipt(job,config);const update=await db.from('message_outbox').update({...result,updated_at:new Date().toISOString()}).eq('id',job.id).eq('state','sent');if(update.error)throw update.error;return Response.json({id:job.id,state:result.state});}
  return Response.json({state:'idle'});
 }catch{return Response.json({error:'Message worker failed'},{status:503});}
});

export function xml(value){return String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&apos;');}
export function smsXml(job,c){return `<?xml version="1.0" encoding="UTF-8"?><smspack ka="${xml(c.user)}" pwd="${xml(c.password)}" org="${xml(c.sender)}"><mesaj><metin>${xml(job.body)}</metin><nums>${xml(job.recipient)},</nums></mesaj></smspack>`;}
export function parseSend(text){const match=/^\$(\d+)(?:#[\d.]+)?$/.exec(text.trim());return match?{state:'sent',provider_id:match[1]}:{state:'failed',safe_error:'Sağlayıcı gönderimi reddetti.'};}
export function parseReceipt(text,recipient){const digits=v=>v.replace(/\D/g,'').replace(/^0/,'90');const line=text.trim().split(/\r?\n/).map(l=>l.trim().split(/\s+/)).find(parts=>digits(parts[0])===digits(recipient));if(!line)return {state:'sent'};const code=Number(line[1]);if(code===3)return {state:'delivered'};if([5,6,7,12,13,15,16,17,18,19,20,21,22].includes(code))return {state:'failed',safe_error:'SMS teslim edilemedi ('+code+').'};return {state:'sent'};}
export async function deliver(job,config,fetcher=fetch){
 if(job.delivery_mode==='test')return {state:'delivered',provider_id:'test-'+job.id};
 if(job.delivery_mode==='live'&&config.mode!=='live')return {state:'failed',safe_error:'Canlı gönderim kapatılmış. İçeriği inceleyip yeni gönderim oluşturun.'};
 if(config.mode==='test')return {state:'delivered',provider_id:'test-'+job.id};
 if(config.mode!=='live')throw new Error('Provider mode must be test or live');
 if(job.channel==='sms'){
  if(!config.sms?.user||!config.sms?.password||!config.sms?.sender)throw new Error('SMS provider not configured');
  const response=await fetcher('https://smsgw.mutlucell.com/smsgw-ws/sndblkex',{method:'POST',headers:{'Content-Type':'text/xml; charset=UTF-8'},body:smsXml(job,config.sms),signal:AbortSignal.timeout(20000)});
  if(!response.ok)throw new Error('SMS delivery result uncertain');return parseSend(await response.text());
 }
 if(!config.email?.key||!config.email?.from)throw new Error('Email provider not configured');
 const response=await fetcher('https://api.resend.com/emails',{method:'POST',headers:{Authorization:'Bearer '+config.email.key,'Content-Type':'application/json','Idempotency-Key':job.id},body:JSON.stringify({from:config.email.from,to:[job.recipient],subject:job.subject,text:job.body}),signal:AbortSignal.timeout(20000)});
 if(!response.ok)throw new Error('Email delivery result uncertain');const result=await response.json();if(!result.id)throw new Error('Email provider response invalid');return {state:'sent',provider_id:result.id};
}
export async function receipt(job,config,fetcher=fetch){
 if(job.channel!=='sms')return {state:'sent'};
 const response=await fetcher('https://smsgw.mutlucell.com/smsgw-ws/gtblkrprtex',{method:'POST',headers:{'Content-Type':'text/xml; charset=UTF-8'},body:`<?xml version="1.0" encoding="UTF-8"?><smsrapor ka="${xml(config.sms.user)}" pwd="${xml(config.sms.password)}" id="${xml(job.provider_id)}"/>`,signal:AbortSignal.timeout(20000)});
 if(!response.ok)throw new Error('Receipt unavailable');return parseReceipt(await response.text(),job.recipient);
}
